	"strconv"
	"strings"
)

type Accumulator struct {
	value int
}

func NewAccumulator(start int) *Accumulator {
	return &Accumulator{value: start}
}

func (a *Accumulator) Apply(command string) error {
	if command == "reset" {
		a.value = 0
		return nil
	}

	operation, operandText, found := strings.Cut(command, ":")
	if !found {
		return errors.New("invalid command")
	}
	operand, err := strconv.Atoi(operandText)
	if err != nil {
		return errors.New("invalid command")
	}

	switch operation {
	case "add":
		a.value += operand
		return nil
	case "mul":
		a.value *= operand
		return nil
	default:
		return errors.New("invalid command")
	}
}

func (a *Accumulator) Value() int {
	return a.value
}
