{"items":[{"id":"cap-v2-sequence_algorithms-go-repair-01","test_code":"package solution

import (
	"reflect"
	"testing"
)

func TestMergeUniqueMergesAndDeduplicates(t *testing.T) {
	left := []int{-5, -5, -1, 2, 2, 7, 10}
	right := []int{-5, 0, 0, 2, 3, 10, 10, 12}
	leftBefore := append([]int(nil), left...)
	rightBefore := append([]int(nil), right...)

	got := MergeUnique(left, right)
	want := []int{-5, -1, 0, 2, 3, 7, 10, 12}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("MergeUnique() = %v, want %v", got, want)
	}
	if !reflect.DeepEqual(left, leftBefore) {
		t.Fatalf("left input modified: got %v, want %v", left, leftBefore)
	}
	if !reflect.DeepEqual(right, rightBefore) {
		t.Fatalf("right input modified: got %v, want %v", right, rightBefore)
	}
}

func TestMergeUniqueEmptyInputs(t *testing.T) {
	tests := []struct {
		name  string
		left  []int
		right []int
		want  []int
	}{
		{name: "both nil", left: nil, right: nil, want: []int{}},
		{name: "left empty", left: []int{}, right: []int{1, 1, 2}, want: []int{1, 2}},
		{name: "right empty", left: []int{-2, -2, 4}, right: []int{}, want: []int{-2, 4}},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			got := MergeUnique(tc.left, tc.right)
			if !reflect.DeepEqual(got, tc.want) && !(len(got) == 0 && len(tc.want) == 0) {
				t.Fatalf("MergeUnique(%v, %v) = %v, want %v", tc.left, tc.right, got, tc.want)
			}
		})
	}
}

func TestMergeUniqueAllDuplicatesAndDisjointRanges(t *testing.T) {
	tests := []struct {
		name        string
		left, right []int
		want        []int
	}{
		{
			name:  "all duplicates",
			left:  []int{4, 4, 4},
			right: []int{4, 4},
			want:  []int{4},
		},
		{
			name:  "right values precede left",
			left:  []int{5, 6, 6},
			right: []int{-3, -3, 0},
			want:  []int{-3, 0, 5, 6},
		},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			if got := MergeUnique(tc.left, tc.right); !reflect.DeepEqual(got, tc.want) {
				t.Fatalf("MergeUnique() = %v, want %v", got, tc.want)
			}
		})
	}
}

func TestMergeUniqueIntegerBoundaries(t *testing.T) {
	maxInt := int(^uint(0) >> 1)
	minInt := -maxInt - 1
	left := []int{minInt, minInt, 0, maxInt}
	right := []int{minInt, -1, maxInt, maxInt}
	want := []int{minInt, -1, 0, maxInt}

	if got := MergeUnique(left, right); !reflect.DeepEqual(got, want) {
		t.Fatalf("MergeUnique() = %v, want %v", got, want)
	}
}
