import (
	"reflect"
	"testing"
)

func TestRepeatIndicesSeparatedAndAdjacentRepeats(t *testing.T) {
	values := []string{"red", "blue", "red", "red", "green", "blue", "green", "green"}
	before := append([]string(nil), values...)
	want := []int{2, 3, 5, 6, 7}

	got := RepeatIndices(values)
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("RepeatIndices() = %v, want %v", got, want)
	}
	if !reflect.DeepEqual(values, before) {
		t.Fatalf("input modified: got %v, want %v", values, before)
	}
}

func TestRepeatIndicesEmptyAndNoRepeats(t *testing.T) {
	tests := []struct {
		name   string
		values []string
	}{
		{name: "nil", values: nil},
		{name: "empty", values: []string{}},
		{name: "single", values: []string{"only"}},
		{name: "all distinct", values: []string{"a", "b", "c"}},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			if got := RepeatIndices(tc.values); len(got) != 0 {
				t.Fatalf("RepeatIndices(%v) = %v, want no indices", tc.values, got)
			}
		})
	}
}

func TestRepeatIndicesEveryOccurrenceAfterFirst(t *testing.T) {
	values := []string{"same", "same", "same", "same"}
	want := []int{1, 2, 3}
	if got := RepeatIndices(values); !reflect.DeepEqual(got, want) {
		t.Fatalf("RepeatIndices() = %v, want %v", got, want)
	}
}

func TestRepeatIndicesTreatsStringsExactly(t *testing.T) {
	values := []string{"", "A", "a", "", "A", " a", "a"}
	want := []int{3, 4, 6}
	if got := RepeatIndices(values); !reflect.DeepEqual(got, want) {
		t.Fatalf("RepeatIndices() = %v, want %v", got, want)
	}
}
"},{"id":"cap-v2-stateful_workflows-go-generation-01","test_code":"package solution

import (
	"reflect"
	"testing"
)

func requireRevisionSnapshot(t *testing.T, store *RevisionStore, wantVersion uint64, wantValues []string) {
	t.Helper()
	gotVersion, gotValues := store.Snapshot()
	if gotVersion != wantVersion {
		t.Fatalf("Snapshot version = %d, want %d", gotVersion, wantVersion)
	}
	if !reflect.DeepEqual(gotValues, wantValues) && !(len(gotValues) == 0 && len(wantValues) == 0) {
		t.Fatalf("Snapshot values = %v, want %v", gotValues, wantValues)
	}
}

func TestRevisionStoreCommitVersioningAndMismatch(t *testing.T) {
	store := NewRevisionStore([]string{"initial"})
	requireRevisionSnapshot(t, store, 0, []string{"initial"})

	if store.Commit(1, []string{"wrong"}) {
		t.Fatal("Commit succeeded with a mismatched version")
	}
	requireRevisionSnapshot(t, store, 0, []string{"initial"})

	if !store.Commit(0, []string{"first", "revision"}) {
		t.Fatal("Commit failed with the current version")
	}
	requireRevisionSnapshot(t, store, 1, []string{"first", "revision"})

	if store.Commit(0, []string{"stale"}) {
		t.Fatal("Commit succeeded with a stale version")
	}
	requireRevisionSnapshot(t, store, 1, []string{"first", "revision"})
}

func TestRevisionStoreUndoOrderAndVersioning(t *testing.T) {
	store := NewRevisionStore([]string{"zero"})
	if !store.Commit(0, []string{"one"}) {
		t.Fatal("first commit failed")
	}
	if !store.Commit(1, []string{"two"}) {
		t.Fatal("second commit failed")
	}

	if !store.Undo() {
		t.Fatal("first Undo returned false")
	}
	requireRevisionSnapshot(t, store, 3, []string{"one"})

	if !store.Undo() {
		t.Fatal("second Undo returned false")
	}
	requireRevisionSnapshot(t, store, 4, []string{"zero"})

	if store.Undo() {
		t.Fatal("Undo succeeded with no saved revision")
	}
	requireRevisionSnapshot(t, store, 4, []string{"zero"})
}

func TestRevisionStoreCommitAfterUndo(t *testing.T) {
	store := NewRevisionStore([]string{"base"})
