import "testing"

func TestAccumulatorValidTransitions(t *testing.T) {
	a := NewAccumulator(7)
	steps := []struct {
		command string
		want    int
	}{
		{command: "add:5", want: 12},
		{command: "mul:-2", want: -24},
		{command: "add:+4", want: -20},
		{command: "reset", want: 0},
		{command: "add:-3", want: -3},
		{command: "mul:0", want: 0},
	}

	for _, step := range steps {
		if err := a.Apply(step.command); err != nil {
			t.Fatalf("Apply(%q) returned error: %v", step.command, err)
		}
		if got := a.Value(); got != step.want {
			t.Fatalf("after Apply(%q), Value() = %d, want %d", step.command, got, step.want)
		}
	}
}

func TestAccumulatorMalformedCommandsLeaveValueUnchanged(t *testing.T) {
	commands := []string{
		"",
		"add",
		"mul",
		"reset:",
		"reset:0",
		"add:",
		"mul:",
		"add:1:2",
		"mul:-2:3",
		"subtract:1",
		"ADD:1",
		" add:1",
		"add: 1",
		"add:1 ",
		"add:1.0",
		"add:0x10",
		"mul:--2",
		"mul:+-2",
	}

	for _, command := range commands {
		t.Run(command, func(t *testing.T) {
			a := NewAccumulator(41)
			if err := a.Apply(command); err == nil {
				t.Fatalf("Apply(%q) returned nil error", command)
			}
			if got := a.Value(); got != 41 {
				t.Fatalf("Apply(%q) changed value to %d, want 41", command, got)
			}
		})
	}
}

func TestAccumulatorMalformedCommandDoesNotDisruptLaterCommands(t *testing.T) {
	a := NewAccumulator(10)
	if err := a.Apply("add:not-a-number"); err == nil {
		t.Fatal("malformed command returned nil error")
	}
	if got := a.Value(); got != 10 {
		t.Fatalf("malformed command changed value to %d, want 10", got)
	}
	if err := a.Apply("mul:3"); err != nil {
		t.Fatalf("valid command after malformed command returned error: %v", err)
	}
	if got := a.Value(); got != 30 {
		t.Fatalf("final Value() = %d, want 30", got)
	}
}

func TestAccumulatorIntegerBoundaries(t *testing.T) {
	maxInt := int(^uint(0) >> 1)
	minInt := -maxInt - 1

	a := NewAccumulator(maxInt)
	if err := a.Apply("add:0"); err != nil {
		t.Fatalf("Apply(add:0) returned error: %v", err)
	}
	if got := a.Value(); got != maxInt {
		t.Fatalf("Value() = %d, want max int %d", got, maxInt)
	}

	b := NewAccumulator(minInt)
	if err := b.Apply("mul:1"); err != nil {
		t.Fatalf("Apply(mul:1) returned error: %v", err)
	}
	if got := b.Value(); got != minInt {
		t.Fatalf("Value() = %d, want min int %d", got, minInt)
	}
}

func TestAccumulatorRejectsOutOfRangeOperandsWithoutMutation(t *testing.T) {
	maxInt := int(^uint(0) >> 1)
	tooLarge := uint64(maxInt) + 1
	a := NewAccumulator(9)

	command := "add:" + decimalUint64(tooLarge)
	if err := a.Apply(command); err == nil {
		t.Fatalf("Apply(%q) returned nil error for out-of-range int", command)
	}
	if got := a.Value(); got != 9 {
		t.Fatalf("out-of-range operand changed value to %d, want 9", got)
	}
}

func decimalUint64(value uint64) string {
	if value == 0 {
		return "0"
	}
	var digits [20]byte
	position := len(digits)
	for value > 0 {
		position--
		digits[position] = byte('0' + value%10)
		value /= 10
	}
	return string(digits[position:])
}
