{"items":[{"id":"cap-v2-stateful_workflows-go-repair-02","test_code":"package solution

import "testing"

func TestCounterAppliesStepsAndReportsValue(t *testing.T) {
	c := NewCounter(10)

	got, err := c.Apply("tx-1", " +5; -3 ;+10 ")
	if err != nil {
		t.Fatalf("Apply returned unexpected error: %v", err)
	}
	if got != 22 {
		t.Fatalf("Apply result = %d, want 22", got)
	}
	if gotValue := c.Value(); gotValue != 22 {
		t.Fatalf("Value() = %d, want 22", gotValue)
	}
}

func TestCounterCompletedTransactionIsIdempotent(t *testing.T) {
	c := NewCounter(4)

	first, err := c.Apply("same", "+6;-2")
	if err != nil {
		t.Fatalf("first Apply returned error: %v", err)
	}
	second, err := c.Apply("same", "+1000")
	if err != nil {
		t.Fatalf("reused Apply returned error: %v", err)
	}
	if first != 8 || second != 8 {
		t.Fatalf("results = (%d, %d), want (8, 8)", first, second)
	}
	if got := c.Value(); got != 8 {
		t.Fatalf("Value() after transaction reuse = %d, want 8", got)
	}
}

func TestCounterMalformedTransactionIsAtomicAndRetryable(t *testing.T) {
	c := NewCounter(20)

	got, err := c.Apply("retryable", "+7;broken;-2")
	if err == nil {
		t.Fatal("malformed transaction returned nil error")
	}
